class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = RollingWindow[float](100)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {
            ticker: data.bars.get(symbol)
            for ticker, symbol in self.symbols.items()
        }

        spy_bar = bars["SPY"]
        spy_close = float(spy_bar.close) if spy_bar is not None else None
        spy_average = None
        if spy_close is not None:
            self.spy_closes.add(spy_close)
            if self.spy_closes.is_ready:
                spy_average = sum(self.spy_closes) / self.spy_closes.count

        aapl_bar = bars["AAPL"]
        aapl_close = float(aapl_bar.close) if aapl_bar is not None else None
        if aapl_close is not None:
            if self.previous_aapl_close is not None and aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        complete_slice = all(bar is not None for bar in bars.values())
        if complete_slice:
            # Sells are evaluated before buys for both independent strategies.
            if self.strategy_a_shares > 0 and self._spy_crosses_below(
                spy_close, spy_average
            ):
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
            ):
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and self._spy_crosses_above(
                spy_close, spy_average
            ):
                quantity = int(
                    (self.portfolio.total_portfolio_value * 0.40) / spy_close
                )
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                if self.portfolio.cash >= 20_000:
                    quantity = int(20_000 / aapl_close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

        if spy_close is not None and spy_average is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average
        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def _spy_crosses_above(self, close, average):
        return (
            average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

    def _spy_crosses_below(self, close, average):
        return (
            average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_average is not None
            and self.previous_spy_close >= self.previous_spy_average
            and close < average
        )

