        present = {ticker: bars.ContainsKey(symbol) for ticker, symbol in self.symbols.items()}

        spy_bar = bars[self.symbols["SPY"]] if present["SPY"] else None
        aapl_bar = bars[self.symbols["AAPL"]] if present["AAPL"] else None

