        spy_cross_history_ready = self.spy_previous_close is not None and self.spy_previous_sma is not None

        if all_bars_present and all_indicators_ready and spy_cross_history_ready:
            spy_sma_today = float(self.spy_sma.Current.Value)
            crossed_above = (
                self.spy_previous_close <= self.spy_previous_sma
