        self.aapl_lot = 0
        self.previous_spy_above_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        # The extra bar allows yesterday's fully formed SMA relationship to be
        # known before a crossover can be acted upon.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
