class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra day supplies the prior close/average needed by a crossover.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Keep private-lot share counts aligned with LEAN's split-adjusted holdings.
        if spy in data.splits and self.strategy_a_shares > 0:
            split = data.splits[spy]
            if split.type == SplitType.SPLIT_OCCURRED:
                self.strategy_a_shares = round(
                    self.strategy_a_shares / float(split.split_factor)
                )
        if aapl in data.splits and self.strategy_b_shares > 0:
            split = data.splits[aapl]
            if split.type == SplitType.SPLIT_OCCURRED:
                self.strategy_b_shares = round(
                    self.strategy_b_shares / float(split.split_factor)
                )

        if spy in data.bars:
            self.spy_closes.append(float(data.bars[spy].close))

        if aapl in data.bars:
            aapl_bar = data.bars[aapl]
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        # Every strategy rule is skipped unless the complete subscribed slice exists.
        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return
        if self.is_warming_up or len(self.spy_closes) < 101 or not self.aapl_rsi.is_ready:
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_average = sum(list(self.spy_closes)[-100:]) / 100.0
        spy_previous_average = sum(list(self.spy_closes)[:100]) / 100.0

        # Strategy A: sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if spy_previous_close >= spy_previous_average and spy_close < spy_average:
                self.market_order(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif spy_previous_close <= spy_previous_average and spy_close > spy_average:
            quantity = floor(0.40 * self.portfolio.total_portfolio_value / spy_close)
            if quantity > 0:
                self.market_order(spy, quantity)
                self.strategy_a_shares = quantity

        # Strategy B: sells are evaluated before buys.
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0
