            symbol in data.Bars for symbol in self.symbols.values()
        )

        indicators_ready = (
            spy_sma is not None
            and self.spy_previous_sma is not None
            and self.spy_previous_close is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.IsReady
        )

        if not self.IsWarmingUp and all_bars_present and indicators_ready:
            # Evaluate every sell before either strategy's buy.
