        aapl_bar = self._bar(data, self.symbols["AAPL"])

        previous_spy_close = self.previous_spy_close
        previous_spy_average = self.previous_spy_average
        current_spy_average = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == 100:
                current_spy_average = sum(self.spy_closes) / 100.0
            self.previous_spy_close = float(spy_bar.Close)
            self.previous_spy_average = current_spy_average

        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)
            if (
                self.previous_aapl_close is not None
                and current_aapl_close < self.previous_aapl_close
            ):
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = current_aapl_close

