        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"],
            14,
            MovingAverageType.WILDERS,
            Resolution.DAILY,
        )

        self.previous_closes = {}
        self.previous_spy_relation = None
        self.aapl_red_streak = 0

        # These quantities are private to their respective strategies.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Update continuously-computed market state for every bar that arrived,
        # even when another subscription is absent and trading must be skipped.
        if "AAPL" in bars:
            aapl_close = bars["AAPL"].close
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None and aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

        current_spy_relation = None
        if "SPY" in bars and self.spy_sma.is_ready:
            current_spy_relation = bars["SPY"].close - self.spy_sma.current.value

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        if all_bars_present and indicators_ready and not self.is_warming_up:
            spy_crossed_above = (
                self.previous_spy_relation is not None
                and self.previous_spy_relation <= 0
                and current_spy_relation > 0
            )
            spy_crossed_below = (
                self.previous_spy_relation is not None
                and self.previous_spy_relation >= 0
                and current_spy_relation < 0
            )

            # All sells are evaluated before either strategy's buy.
            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crossed_above:
                quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                if self.portfolio.cash >= 20_000:
                    quantity = int(20_000 // bars["AAPL"].close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

        if current_spy_relation is not None:
            self.previous_spy_relation = current_spy_relation

