class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {ticker: None for ticker in tickers}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # The lots are private strategy state, even though LEAN aggregates their
        # shares in the portfolio holdings collection.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market-state quantities continue to consume every available bar, even
        # when a missing subscription prevents the strategies from acting today.
        for ticker, symbol in self.symbols.items():
            if symbol not in bars:
                continue

            bar = bars[symbol]
            close = bar.Close

            if ticker == "SPY":
                self.spy_sma.Update(bar.EndTime, close)
            elif ticker == "AAPL":
                previous_close = self.previous_closes[ticker]
                if previous_close is None or close >= previous_close:
                    self.aapl_red_streak = 0
                else:
                    self.aapl_red_streak += 1
                self.aapl_rsi.Update(bar.EndTime, close)

        if any(symbol not in bars for symbol in self.symbols.values()):
            self._save_previous_values(bars)
            return

        spy_bar = bars[self.symbols["SPY"]]
        aapl_bar = bars[self.symbols["AAPL"]]

        # Sells are evaluated before buys. Each side is evaluated only in the
        # state in which its corresponding private lot permits it.
        if self.strategy_a_shares > 0:
            if self._spy_crossed_below(spy_bar.Close):
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif self._spy_crossed_above(spy_bar.Close):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif (
            self.aapl_rsi.IsReady
            and self.previous_closes["AAPL"] is not None
            and self.aapl_red_streak >= 3
        ):
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

        self._save_previous_values(bars)

    def _spy_crossed_above(self, close):
        return (
            self.spy_sma.IsReady
            and self.previous_closes["SPY"] is not None
            and self.previous_spy_sma is not None
            and self.previous_closes["SPY"] <= self.previous_spy_sma
            and close > self.spy_sma.Current.Value
        )

    def _spy_crossed_below(self, close):
        return (
            self.spy_sma.IsReady
            and self.previous_closes["SPY"] is not None
            and self.previous_spy_sma is not None
            and self.previous_closes["SPY"] >= self.previous_spy_sma
            and close < self.spy_sma.Current.Value
        )

    def _save_previous_values(self, bars):
        for ticker, symbol in self.symbols.items():
            if symbol in bars:
                self.previous_closes[ticker] = bars[symbol].Close

        if self.symbols["SPY"] in bars and self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value

