        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state data advances whenever that ticker has a bar, even when
        # a missing bar elsewhere prevents this day's rules from being run.
        spy_bar = bars.get("SPY")
        previous_spy_close = self.spy_closes[-1] if self.spy_closes else None
        previous_spy_sma = None
        if len(self.spy_closes) >= 100:
            previous_spy_sma = sum(list(self.spy_closes)[-100:]) / 100
        if spy_bar is not None:
            self.spy_closes.append(spy_bar.close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.aapl_previous_close is None or aapl_bar.close >= self.aapl_previous_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_previous_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if len(bars) != len(self.symbols) or self.is_warming_up:
            return
        if len(self.spy_closes) < 101 or not self.aapl_rsi.is_ready:
            return

        spy_close = spy_bar.close
        current_spy_sma = sum(list(self.spy_closes)[-100:]) / 100
        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        # Sells are evaluated before buys.
        if self.strategy_a_quantity > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if self.strategy_b_quantity > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if self.portfolio.cash >= allocation:
                quantity = int(allocation // aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_quantity = quantity

