            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.spy_comparisons = RollingWindow[bool](2)

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_closes = RollingWindow[float](4)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                self.spy_comparisons.Add(spy_bar.Close > self.spy_sma.Current.Value)

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.aapl_closes.Add(aapl_bar.Close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[spy]
        aapl_bar = data.Bars[aapl]

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and self.spy_comparisons.IsReady:
            crossed_below = self.spy_comparisons[1] and not self.spy_comparisons[0]
            if crossed_below:
                self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")
                self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B sell")
                self.aapl_lot = 0

        if self.spy_lot == 0 and self.spy_comparisons.IsReady:
            crossed_above = not self.spy_comparisons[1] and self.spy_comparisons[0]
            if crossed_above:
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close
                )
                if quantity > 0:
                    self.MarketOrder(spy, quantity, tag="Strategy A buy")
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_closes.IsReady:
            red_for_three_days = (
                self.aapl_closes[0] < self.aapl_closes[1]
                and self.aapl_closes[1] < self.aapl_closes[2]
                and self.aapl_closes[2] < self.aapl_closes[3]
            )
            if red_for_three_days and self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity, tag="Strategy B buy")
                    self.aapl_lot = quantity

